import type { Metadata } from "next";
import Link from "next/link";
import { startIntroductionCheckout } from "@/app/actions/billing";
import { requireOrganization } from "@/lib/auth";
import { createClient } from "@/lib/supabase/server";
import { DashboardShell } from "@/components/dashboard-shell";
export const metadata: Metadata = { title: "Vendor billing" }; export const dynamic = "force-dynamic";
type OfferInfo = { annual_price: number; currency: string; vendor_products: { product_name: string } | { product_name: string }[] };
export default async function BillingPage({ searchParams }: { searchParams: Promise<{ checkout?: string; error?: string; paid?: string }> }) {
  const notice = await searchParams; const { organization } = await requireOrganization("vendor"); const supabase = await createClient();
  const [{ data: introductions }, { data: payments }] = await Promise.all([
    supabase.from("introductions").select("id,selection_id,status,created_at").eq("vendor_organization_id", organization.organizationId).order("created_at", { ascending: false }),
    supabase.from("payments").select("id,selection_id,amount,currency,status,provider_receipt_url,created_at").eq("vendor_organization_id", organization.organizationId).order("created_at", { ascending: false })
  ]);
  const selectionIds = (introductions ?? []).map((item) => item.selection_id); const { data: selections } = selectionIds.length ? await supabase.from("selections").select("id,offer_id,offers!selections_offer_id_fkey(annual_price,currency,vendor_products(product_name))").in("id", selectionIds) : { data: [] };
  const selectionMap = new Map((selections ?? []).map((selection) => [selection.id, selection])); const paymentMap = new Map((payments ?? []).map((payment) => [payment.selection_id, payment]));
  const stripeConfigured = Boolean(process.env.STRIPE_SECRET_KEY && process.env.STRIPE_WEBHOOK_SECRET && process.env.STRIPE_VENDOR_INTRODUCTION_PRICE_ID);
  return <DashboardShell area="Vendor" organization={organization.name}><div className="page-back"><Link href="/vendor">← Vendor dashboard</Link></div>{notice.checkout === "success" && <div className="notice-success">Checkout completed. Stripe is confirming the payment through the signed webhook.</div>}{notice.checkout === "cancelled" && <p className="form-error">Checkout was cancelled. Nothing was charged.</p>}{notice.error && <p className="form-error">Checkout is unavailable because payment configuration is incomplete or the introduction is no longer payable.</p>}
    <div className="dashboard-heading"><div><span className="eyebrow">Billing</span><h1>Pay only when picked.</h1><p className="heading-copy">Browsing and challenges are free. A selected challenge costs €99 once, unlocking the buyer introduction.</p></div><span className="badge">€99 / introduction</span></div>
    {!stripeConfigured && <div className="configuration-notice"><strong>Stripe configuration required</strong><span>Add `STRIPE_SECRET_KEY` and `STRIPE_WEBHOOK_SECRET` to enable live Checkout. The Price ID is already known.</span></div>}
    <div className="billing-list">{introductions?.map((intro) => { const selection = selectionMap.get(intro.selection_id); const rawOffer = selection?.offers as OfferInfo | OfferInfo[] | undefined; const offer = Array.isArray(rawOffer) ? rawOffer[0] : rawOffer; const productRelation = offer?.vendor_products; const product = Array.isArray(productRelation) ? productRelation[0] : productRelation; const payment = paymentMap.get(intro.selection_id); return <article className="billing-row" key={intro.id}><div><span className="card-kicker">Selected challenge</span><h2>{product?.product_name ?? "BeatMyVendor introduction"}</h2><p>{offer ? `${new Intl.NumberFormat("en", { style: "currency", currency: offer.currency, maximumFractionDigits: 0 }).format(Number(offer.annual_price))} annual offer` : "Offer selected"}</p></div><div className="billing-action"><span className={`badge badge-${payment?.status ?? intro.status}`}>{payment?.status ?? intro.status.replaceAll("_", " ")}</span>{intro.status === "awaiting_payment" && (!payment || ["pending","failed","cancelled"].includes(payment.status)) && <form action={startIntroductionCheckout}><input type="hidden" name="selectionId" value={intro.selection_id} /><button className="button button-primary" disabled={!stripeConfigured}>{payment?.status === "pending" ? "Resume secure checkout" : "Pay €99"}</button></form>}{intro.status === "introduced" && <Link className="button button-secondary" href="/vendor/introductions">View introduction</Link>}</div></article>; })}{!introductions?.length && <div className="empty-panel"><h2>No introduction fees.</h2><p>You are charged only after a buyer selects your challenge.</p></div>}</div>
    <section className="detail-card billing-history"><span className="card-kicker">Payment history</span><h2>Receipts</h2>{payments?.length ? payments.map((payment) => <div className="challenge-row" key={payment.id}><div><strong>Introduction fee · {new Intl.NumberFormat("en", { style: "currency", currency: payment.currency.toUpperCase() }).format(payment.amount / 100)}</strong><span>{new Intl.DateTimeFormat("en", { dateStyle: "medium" }).format(new Date(payment.created_at))}</span></div><div className="row-actions"><span className={`badge badge-${payment.status}`}>{payment.status}</span>{payment.provider_receipt_url && <a className="button button-secondary" href={payment.provider_receipt_url} target="_blank" rel="noreferrer">Receipt</a>}</div></div>) : <p>No payments yet.</p>}</section>
  </DashboardShell>;
}
